"""Synthetic lease policy for the bulk-reader pilot."""
DEFAULT_TTL_SECONDS = 900
PROJECT_TTL_SECONDS = {"atlas": 1800}
RENEWAL_CAP_SECONDS = 600

def ttl_seconds(project: str, *, renewal: bool = False) -> int:
    ttl = PROJECT_TTL_SECONDS.get(project, DEFAULT_TTL_SECONDS)
    if renewal:
        return min(ttl, RENEWAL_CAP_SECONDS)
    return ttl

