"""Synthetic profile persistence example."""
def save_profile(store, cache, profile):
    store.write(profile)
    store.commit()
    cache.pop(profile.id, None)
    return profile.id

def load_profile(store, cache, profile_id):
    if profile_id not in cache:
        cache[profile_id] = store.read(profile_id)
    return cache[profile_id]

