"""Synthetic storage contract used by profiles.py."""
class CommitFailed(RuntimeError):
    pass

class Store:
    def commit(self):
        """Return on success; raise CommitFailed on failure. No hidden retries."""
        if self.fail_commit:
            raise CommitFailed("commit failed")
        self.committed = True
